from __future__ import annotations
import streamlit as st

CSS = '''<style>
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono&family=Space+Grotesk:wght@500;600;700&display=swap');
:root{--bg:#070B14;--surface:rgba(255,255,255,.04);--border:rgba(255,255,255,.08);--text:#E6EDF7;--muted:#8A97AD;--cyan:#22D3EE;--violet:#8B5CF6;--green:#22C55E;--amber:#F59E0B;--red:#EF4444}*{box-sizing:border-box}html,body,[class*="css"]{font-family:Inter,system-ui,sans-serif;color:var(--text)}body{background:var(--bg)}h1,h2,h3{font-family:"Space Grotesk",sans-serif;letter-spacing:-.04em}.stApp{background:radial-gradient(circle at 5% 0%,#10224155,transparent 30%),var(--bg)}#MainMenu,footer,header,[data-testid="stSidebar"],[data-testid="collapsedControl"],[data-testid="stDeployButton"]{display:none!important}.block-container{max-width:1200px;padding-top:1rem;padding-bottom:3rem}.glass,.result-card,.step-card,.metric-card{background:var(--surface);border:1px solid var(--border);border-radius:18px;backdrop-filter:blur(14px);box-shadow:0 14px 42px #0003;transition:transform .25s cubic-bezier(.2,.8,.2,1),border-color .25s}.glass:hover,.result-card:hover,.step-card:hover,.metric-card:hover{transform:translateY(-4px);border-color:#22d3ee55}.hero{position:relative;overflow:hidden;padding:4rem 0 2rem}.blob{position:absolute;width:360px;height:360px;border-radius:50%;filter:blur(70px);opacity:.18;pointer-events:none;animation:drift 20s ease-in-out infinite alternate}.b1{background:var(--cyan);top:-160px;left:-90px}.b2{background:var(--violet);right:-100px;top:80px;animation-delay:-8s}.b3{background:#2563eb;left:40%;bottom:-250px;animation-delay:-14s}@keyframes drift{to{transform:translate(80px,50px)}}.eyebrow,.pill,.risk{display:inline-flex;align-items:center;gap:.35rem;border:1px solid var(--border);background:#ffffff09;border-radius:999px;padding:.32rem .7rem;font-size:.78rem;font-weight:700}.gradient-text{background:linear-gradient(135deg,var(--cyan),var(--violet));-webkit-background-clip:text;color:transparent}.muted{color:var(--muted)}.gradient-btn button,[data-testid="stBaseButton-primary"]{background:linear-gradient(135deg,var(--cyan),var(--violet))!important;color:#06101a!important;border:0!important;font-weight:800!important;box-shadow:0 8px 22px #22d3ee35!important;transition:transform .18s!important}.gradient-btn button:active,[data-testid="stBaseButton-primary"]:active{transform:scale(.97)}.stTextInput input,.stTextArea textarea,[data-baseweb="input"] input{background:#ffffff08!important;border:1px solid var(--border)!important;border-radius:12px!important;color:var(--text)!important}.stTextInput input:focus,.stTextArea textarea:focus{border-color:var(--cyan)!important;box-shadow:0 0 0 3px #22d3ee22!important}.stFileUploader{border:1px dashed #22d3ee66;border-radius:14px;padding:.5rem;background:#22d3ee08}.stTabs [data-baseweb="tab-list"]{gap:1.2rem}.stTabs [data-baseweb="tab"]{color:var(--muted);font-weight:700}.stTabs [aria-selected="true"]{color:var(--cyan)!important;border-bottom:2px solid var(--cyan)!important}.low{color:var(--green);background:#22c55e22}.medium{color:var(--amber);background:#f59e0b22}.high{color:var(--red);background:#ef444422}.info{color:var(--cyan);background:#22d3ee22}.nav{position:sticky;top:0;z-index:20;display:flex;align-items:center;justify-content:space-between;padding:.55rem 0;background:#070b14dd;backdrop-filter:blur(18px);border-bottom:1px solid var(--border)}.brand{font:700 1.35rem "Space Grotesk";display:flex;gap:.5rem;align-items:center}.shield{filter:drop-shadow(0 0 8px #22d3ee);animation:pulse 2.6s infinite}.nav-status{font-size:.75rem;color:var(--cyan)}@keyframes pulse{50%{transform:scale(1.08);opacity:.8}}.hero-svg{width:100%;max-width:450px;margin:auto;display:block}.scanline{animation:sweep 2.2s ease-in-out infinite}@keyframes sweep{0%,100%{transform:translateY(0)}50%{transform:translateY(200px)}}.mini{animation:bob 3s ease-in-out infinite alternate}@keyframes bob{to{transform:translateY(-10px)}}.stat-strip,.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.metric-card{padding:1rem}.metric-card strong{font:700 1.65rem "Space Grotesk";display:block}.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:13px}.step-card{padding:1rem;animation:up .6s both}.step-card:nth-child(2){animation-delay:.12s}.step-card:nth-child(3){animation-delay:.24s}.step-card:nth-child(4){animation-delay:.36s}@keyframes up{from{opacity:0;transform:translateY(14px)}}.badge{display:grid;place-items:center;width:28px;height:28px;border-radius:9px;background:linear-gradient(135deg,var(--cyan),var(--violet));color:#06101a;font-weight:900}.scanner{height:220px;border:1px dashed #22d3ee66;border-radius:18px;display:grid;place-items:center;position:relative;overflow:hidden;color:var(--muted)}.scanner:after{content:"";position:absolute;height:2px;width:90%;background:var(--cyan);box-shadow:0 0 18px var(--cyan);animation:scan 2s infinite}@keyframes scan{from{transform:translateY(-80px)}to{transform:translateY(80px)}}.pipeline{display:flex;justify-content:space-between;gap:5px;padding:1rem}.pipe{font-size:.75rem;color:var(--muted);text-align:center}.pipe b{display:grid;place-items:center;width:30px;height:30px;margin:auto auto .35rem;border:2px solid var(--cyan);border-radius:50%;animation:spin .45s linear forwards}@keyframes spin{to{transform:rotate(360deg);background:#22c55e;color:#07120b}}.verdict{padding:1.5rem;display:grid;grid-template-columns:220px 1fr;gap:1.3rem;align-items:center}.gauge{width:210px;overflow:visible}.needle{transform-origin:105px 105px;animation:needle 1.4s cubic-bezier(.2,.8,.2,1) forwards;transform:rotate(-90deg)}@keyframes needle{to{transform:rotate(var(--angle))}}.score{font:700 4rem "Space Grotesk";line-height:1}.reasons{display:grid;gap:.65rem}.reason{padding:.85rem 1rem;border-left:3px solid var(--cyan);background:#ffffff05;border-radius:10px;animation:in .45s both}@keyframes in{from{opacity:0;transform:translateX(-14px)}}.reason:nth-child(2){animation-delay:.09s}.reason:nth-child(3){animation-delay:.18s}.reason:nth-child(4){animation-delay:.27s}.points{float:right;font:700 .8rem "JetBrains Mono"}.timeline{border-left:2px solid #22d3ee55;margin-left:10px;padding-left:1.25rem}.hop{position:relative;padding:0 0 1rem}.hop:before{content:"";position:absolute;left:-1.65rem;top:.25rem;width:.65rem;height:.65rem;border-radius:50%;background:var(--cyan);box-shadow:0 0 10px var(--cyan)}.mono{font-family:"JetBrains Mono",monospace;font-size:.82rem;word-break:break-all}.xray{padding:1rem}.browser{height:120px;border:1px solid var(--border);border-radius:11px;background:linear-gradient(110deg,#ffffff08,#ffffff02,#ffffff08);display:grid;place-items:center;color:var(--muted)}.payload-row{display:flex;justify-content:space-between;padding:.7rem;border-bottom:1px solid var(--border)}.warn-banner{padding:.85rem;border-radius:11px;background:#f59e0b20;color:#fbbf24;border:1px solid #f59e0b55}.footer{text-align:center;color:var(--muted);padding:2rem 0;font-size:.8rem}.stDataFrame{border:1px solid var(--border);border-radius:14px;overflow:hidden}@media(max-width:800px){.stat-strip,.kpis,.steps{grid-template-columns:repeat(2,1fr)}.verdict{grid-template-columns:1fr}.hero{padding-top:2rem}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}
</style>'''

def inject_theme() -> None: st.markdown(CSS, unsafe_allow_html=True)
